// init: The initial user-level program

#include "kernel/include/types.h"
#include "kernel/include/stat.h"
#include "kernel/include/file.h"
#include "kernel/include/fcntl.h"
#include "xv6-user/user.h"

// Automatically generated by Makefile.
#include "xv6-user/init-tests.h"

#define NTESTS (sizeof(cmds) / sizeof(cmds[0]))


int
main(void)
{
  int pid, wpid, status;
  int failed = 0;

  // if(open("console", O_RDWR) < 0){
  //   mknod("console", CONSOLE, 0);
  //   open("console", O_RDWR);
  // }
  if (dev(O_RDWR, CONSOLE, 0) < 0){
    shutdown();
    // shutdown() should never return
    for(;;);
  }

  dup(0);  // stdout
  dup(0);  // stderr

  // running tests
  for(;;){
    for(int i = 0; i < NTESTS; i++){
      pid = fork();

      if(pid < 0){
        printf("init: fork faild\n");
        // parent process must use shutdown
        shutdown();
        for(;;);
      }

      if(pid == 0){
        char *argv[] = {cmds[i], 0};
        exec(cmds[i], argv);
        printf("init: exec %s failed\n", cmds[i]);
        // child process can use exit
        exit(127);
      }

      // parent waits until test finishes
      // to make sure tests are sequential
      for(;;){
        // this call to wait() returns if the shell exits,
        // or if a parentless process exits.
        wpid = wait(&status);
        if(wpid == pid){
          // the shell exited; restart it.
          break;
        } else if(wpid < 0){
          printf("init: wait returned an error\n");
          shutdown();
          for(;;);
        } else {
          // it was a parentless process; do nothing.
        }

        if(status != 0)
          failed++;
      }
    }

    shutdown();
    for(;;);
  }
}
